AssistantMessageToolRequest(name='create', tool_call_id='tooluse_jcbBw7W4sQcOpqDfu9HiQl', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', function() {
    const form = document.getElementById('preferencesForm');
    const radioInputs = document.querySelectorAll('input[name="notification"]');

    radioInputs.forEach(input => {
        input.addEventListener('change', function() {
            updateRadioOptionStates();
        });
    });

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        const selectedValue = document.querySelector('input[name="notification"]:checked').value;
        console.log('Selected notification preference:', selectedValue);

        const formField = document.querySelector('.form-field');
        let successMessage = formField.querySelector('.success-message');

        if (!successMessage) {
            successMessage = document.createElement('div');
            successMessage.className = 'success-message';
            successMessage.textContent = `✓ Preference saved: ${selectedValue.charAt(0).toUpperCase() + selectedValue.slice(1)}`;
            formField.appendChild(successMessage);
        } else {
            successMessage.textContent = `✓ Preference saved: ${selectedValue.charAt(0).toUpperCase() + selectedValue.slice(1)}`;
        }

        successMessage.classList.add('show');

        setTimeout(() => {
            successMessage.classList.remove('show');
        }, 3000);
    });

    function updateRadioOptionStates() {
        radioInputs.forEach(input => {
            const radioOption = input.closest('.radio-option');
            if (input.checked) {
                radioOption.style.backgroundColor = 'rgba(59, 130, 246, 0.1)';
                radioOption.style.borderColor = 'var(--accent)';
            } else {
                radioOption.style.backgroundColor = 'var(--bg-tertiary)';
                radioOption.style.borderColor = 'var(--border)';
            }
        });
    }
});
